"""Bind final round15 main, independent GPU evidence and parent handoff."""
from pathlib import Path
import hashlib,json
P=Path(__file__).resolve().parent;R=P.parents[1];parent=R.parent;C=P.with_name('web-stack-proofs-15-gpu-confirmation-2026-10-10')
read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
v=read(P/'verification.json');c=read(P/'root-confirmation-verification.json');assert v['status']==c['status']=='passed'
for f,h in v['artifact_hashes'].items():assert sha(P/f)==h,f
for f,h in c['artifact_hashes'].items():assert sha(C/f)==h,f
for f in ['confirmation-verification.json','GPU-edge-verification.json']:assert read(C/f)['status']=='passed'
a=read(parent/'agent-ownership.json')['web_stack_proof_batch_15'];assert a['status']=='completed' and a['report_sha256']==sha(P/'REPORT.md') and a['verification_sha256']==sha(P/'verification.json') and a['parent_report_sha256']==sha(parent/'REPORT.md')
assert v['web_samples']+v['native_samples']+c['samples']==a['total_timing_samples']==34668
assert v['web_exact_comparisons']+v['native_exact_comparisons']+c['exact_confirmation_comparisons']+c['exact_edge_comparisons']==a['total_complete_comparisons']==13392
assert v['gpu_samples']+c['samples']==a['actual_gpu_timing_samples']==1620
assert v['web_intervals']+v['native_intervals']+c['intervals_recomputed']==3264
# Reviews precede a provenance-only final audit path correction paragraph.
note='The first final-audit invocation used the repository root for the reduction author’s lane-relative paths and stopped with a missing-file error. The immutable verifier and failed log remain preserved; [corrected path-aware verifier](verify-final-v2.py) authenticates reduction artifacts against their declared lane and external hashes against the repository root. No evidence hashes were changed.\n\n'
reviewed=(P/'REPORT.md').read_text().replace(note,'');assert hashlib.sha256(reviewed.encode()).hexdigest()=='2440bb970a3051665d25b5f8d6949b0538e598f4dff55385f374f91605f47689'
(P/'report-reviewed.md').write_text(reviewed)
review=dict(status='passed',reviewers=['lean_js','lean_runtime','literal_review'],reviewed_report_sha256=sha(P/'report-reviewed.md'),final_report_sha256=sha(P/'REPORT.md'),post_review_change='Only final-audit path-resolution provenance paragraph; final v2 authenticates current REPORT.',scope='Three read-only source/proof/measurement reviews; root binds final manifests separately.',findings=['18general+40static certificates;26old supports offered symmetrically','Pure total wrapping semantics; no float reassociation or once-only callback evaluation guarantee','All42fresh web regressions retained;expertJS/native losses explicit','GPU10/12repeat gains,2inconclusive;312untimededgeGPUcalls separate','Remaining C mapped-array allocation and second reduction loop disclosed'])
(P/'final-report-reviews.json').write_text(json.dumps(review,indent=2)+'\n')
paths=[P/'REPORT.md',P/'verification.json',P/'root-confirmation-verification.json',P/'verify-final.py',P/'verify-final-v2.py',P/'verify-confirmation-root.py',P/'write-report.py',P/'bind-final.py',P/'final-verification.log',P/'final-verification.initial-path-failure.log',P/'report-reviewed.md',P/'final-report-reviews.json',P/'fresh-regressions.json',P/'output-footprint.json',P/'parent-report-before.md',P/'parent-ownership-before.json',parent/'REPORT.md',parent/'agent-ownership.json',C/'confirmation-metadata.json',C/'confirmation-verification.json',C/'GPU-edge-verification.json',C/'browser-results.json',C/'GPU-edge-validation.json',C/'browser-completed.png',R/'bench/web-stack-proofs-15/gpu-confirmation-source/confirmation.py',R/'bench/web-stack-proofs-15/gpu-confirmation-source/gpu-edge-validation.html']
for f in [R/'knowledge/research/web-stack-proofs-15/predicated/evidence.json',R/'knowledge/research/web-stack-proofs-15/predicated/beta-helper-review-evidence.json',R/'knowledge/research/web-stack-proofs-15/reduction/evidence.json']:paths.append(f)
result=dict(status='passed',catalogue_entries=1089,general_laws_added=18,static_certificates_added=40,shared_old_certificates=26,new_composed_certificates=14,snapshot=v['snapshot'],observations=7866,added_observations=1080,current_scoped_tests=31,total_timing_samples=34668,total_complete_comparisons=13392,intervals_recomputed=3264,actual_gpu_timing_samples=1620,untimed_edge_actual_gpu_calls=312,confirmation_prior_counts=c['confirmed_prior_counts'],main_fresh_web_outcomes=read(P/'profitability.json')['fresh_recipe_counts'],expert_native_resident=dict(Ink_faster=12,expert_faster=60,inconclusive=0),broad_expert_superiority_established=False,caller_checks_added=False,measurements_pooled=False,canonical_confirmation_imports=0,final_path_repair_preserved=True,review=review,artifact_hashes={str(f.relative_to(parent)):sha(f) for f in paths})
(P/'final-binding.json').write_text(json.dumps(result,indent=2)+'\n');print({k:d for k,d in result.items() if k not in ['artifact_hashes','review']})
